source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    line_rows = [r for r, row in enumerate(grid) if row and all(v == 2 for v in row)]
    # Preserve the horizontal barrier and any other non-background structure.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 2
    barriers = set(line_rows)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 4:
                if grid[r][c] not in (0, 2):
                    out[r][c] = grid[r][c]
                continue
            nr = r + 1
            if nr < h and nr not in barriers:
                out[nr][c] = 4
                # On reaching the cell immediately above the divider, the 4
                # spreads diagonally upward as it strikes the barrier.
                if any(b == nr + 1 for b in barriers):
                    impact_r = nr
                    for rr in range(impact_r, -1, -1):
                        d = impact_r - rr
                        for cc in (c - d, c + d):
                            if 0 <= cc < w:
                                out[rr][cc] = 4
            else:
                # A 4 already against the divider remains there and makes the same spread.
                out[r][c] = 4
                if nr < h and nr in barriers:
                    for rr in range(r, -1, -1):
                        d = r - rr
                        for cc in (c - d, c + d):
                            if 0 <= cc < w:
                                out[rr][cc] = 4
    return out
